import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun reflect(n: Long): Long {
    if (n == 0L) return 9L
    var x = n
    var res = 0L
    var mul = 1L
    while (x > 0) {
        val d = (x % 10).toInt()
        val rd = 9 - d
        if (rd != 0 || res != 0L) {
            res += rd * mul
            mul *= 10
        }
        x /= 10
    }
    return res
}

fun weight(n: Long): Long {
    return n * reflect(n)
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val l = st.nextToken().toLong()
    val r = st.nextToken().toLong()

    var best = 0L

    fun update(n: Long) {
        if (n in l..r) {
            val w = weight(n)
            if (w > best) best = w
        }
    }

    // Check boundaries
    update(l)
    update(r)

    // Generate candidates of form 10^k - 1 and 10^k
    var p = 1L
    while (p <= 1_000_000_000L) {
        val n1 = p - 1
        val n2 = p
        if (n1 >= l && n1 <= r) update(n1)
        if (n2 >= l && n2 <= r) update(n2)
        p *= 10
    }

    // Additionally, numbers just around powers of 10
    p = 1L
    while (p <= 1_000_000_000L) {
        for (delta in -5L..5L) {
            val n = p + delta
            if (n in l..r) update(n)
        }
        p *= 10
    }

    println(best)
}

