    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val l = st.nextToken().toLong()
    val r = st.nextToken().toLong()

    var ans = 0L

    fun update(n: Long) {
        if (n < l || n > r) return
        val w = n * reflect(n)
        if (w > ans) ans = w
    }

    // candidate 1: r
    update(r)

    // candidate 2: number of all 9s with same digits as r
    val len = r.toString().length
    var all9 = 0L
    repeat(len) { all9 = all9 * 10 + 9 }
    update(all9)

    // candidate 3: smallest number with form 1 followed by (len-1) zeros
    var pow10 = 1L
    repeat(len - 1) { pow10 *= 10 }
    update(pow10)

    // candidate 4: l
    update(l)

    println(ans)
}

